#!/bin/bash
R=$(cd "$(dirname "$0")/.." && pwd); PY=~/Library/Python/3.9/bin/pyocd; T=$R/tools/arm-toolchain/bin/arm-none-eabi; S=${OUT:-/tmp/aio_bench}; cd $R/LPC845; X=LPC845_TWS.axf; ls -la LPC845_TWS.bin | cut -c24-70; date +%H:%M:%S
ad(){ $T-nm $X | grep " $1\$" | cut -d' ' -f1; }
CMDS=(-c "read8 0x$(ad Present_Date_Time) 7" -c "read32 0x$(ad tc2_1s)" -c "read32 0x$(ad time_since_reset_interval)" -c "read8 0x$(ad wake_reason) 1" -c "read32 0x$(ad reset_status)" -c "read32 0x$(ad pAck_xmit)" -c "read32 0x$(ad uart_recv_state)" -c "read8 0x$(ad gc_xmit_buf) 140" -c "read32 0x40048038" -c "halt" -c "reg pc" -c "reg lr" -c "reg sp" -c "reg xpsr" -c "go")
for round in 1 2 3; do got=0; for i in $(seq 1 90); do out=$("$PY" commander -t lpc845 -f 1m -M attach "${CMDS[@]}" 2>&1); case "$out" in *"not detected"*|*"Error while"*) sleep 0.15;; *) echo "=== snapshot $round on try $i at $(date +%H:%M:%S)"; echo "$out" | cut -c1-92; got=1; break;; esac; done; [ $got = 1 ] || { echo "round $round: no connection in 90 tries ($(date +%H:%M:%S))"; }; sleep 2; done
echo; for s in SysTick_Handler HardFault_Handler IntDefaultHandler main wait_tx_idle Get_Cur_Date_Time read_th_val I2C_MasterTransferBlocking; do printf '%s=%s ' $s $(ad $s); done; echo; sed -n 1795,1802p main.c | cut -c1-70; L=$(grep -n '^	Pin_init();' main.c | cut -d: -f1); echo "Pin_init at $L"; grep -n 'GPIO_PortInit' main.c | head -3 | cut -c1-70
